 1	use anyhow::Result;
 2	use crossterm::event::{KeyCode, KeyEvent};
 3	use ratatui::Frame;
 4	use ratatui::style::{Modifier, Style};
 5	use ratatui::text::{Line, Span, Text};
 6	use ratatui::widgets::ListItem;
 7	
 8	use crate::app::App;
 9	
10	use super::chrome;
11	
12	/// Live per-searcher activity: the same `research_stage` rows shown inline in
13	/// the transcript (one per searcher label, updated in place as
14	/// Status/ToolCall events arrive — see `run_searcher` in `app/research.rs`),
15	/// isolated into their own view plus a steer input line.
16	pub(crate) fn render(f: &mut Frame, app: &App) {
17	    let area = crate::ui::centered(f.area(), 76, 70);
18	
19	    let dim = Style::default().fg(app.theme.fg_dim);
20	    let rows: Vec<&crate::db::Message> = app
21	        .messages
22	        .iter()
23	        .filter(|m| m.role == "research_stage")
24	        .collect();
25	    let items: Vec<ListItem> = if rows.is_empty() {
26	        vec![ListItem::new(Line::from(Span::styled(
27	            "waiting for the first update…",
28	            dim,
29	        )))]
30	    } else {
31	        rows.iter()
32	            .map(|m| {
33	                let (label, detail) = m.content.split_once(':').unwrap_or((&m.content, ""));
34	                let detail = detail.trim();
35	                let (glyph, color, detail) = if let Some(rest) = detail.strip_prefix("done —") {
36	                    ("✓", app.theme.success, rest.trim())
37	                } else if let Some(rest) = detail.strip_prefix("error —") {
38	                    ("×", app.theme.error, rest.trim())
39	                } else if let Some(rest) = detail.strip_prefix("working —") {
40	                    ("●", app.theme.accent, rest.trim())
41	                } else {
42	                    ("○", app.theme.fg_dim, detail)
43	                };
44	                let mut lines = vec![Line::from(vec![
45	                    Span::styled(format!("{glyph} "), Style::default().fg(color)),
46	                    Span::styled(
47	                        label.to_string(),
48	                        Style::default().fg(color).add_modifier(Modifier::BOLD),
49	                    ),
50	                ])];
51	                if !detail.is_empty() {
52	                    lines.push(Line::from(vec![
53	                        Span::raw("  "),
54	                        Span::styled(detail.to_string(), Style::default().fg(app.theme.fg_dim)),
55	                    ]));
56	                }
57	                ListItem::new(Text::from(lines))
58	            })
59	            .collect()
60	    };
61	
62	    let inner = chrome::render_frame(
63	        f,
64	        area,
65	        chrome::input_title(
66	            app,
67	            "research agents · steer",
68	            &app.research_live_input,
69	            "type instruction · Enter send · Esc close",
70	        ),
71	        &app.theme,
72	        true,
73	    );
74	    let list = chrome::standard_list(items);
75	    f.render_widget(list, inner);
76	}
77	
78	pub(crate) fn handle_key(app: &mut App, key: KeyEvent) -> Result<()> {
79	    match key.code {
80	        KeyCode::Esc => app.popup = crate::app::Popup::None,
81	        KeyCode::Enter => {
82	            let text = app.research_live_input.trim().to_string();
83	            app.research_live_input.clear();
84	            app.steer_research(&text);
85	        }
86	        KeyCode::Backspace => {
87	            app.research_live_input.pop();
88	        }
89	        KeyCode::Char(c) => app.research_live_input.push(c),
90	        _ => {}
91	    }
92	    Ok(())
93	}

