210	fn writer_messages(topic: &str, verified_draft: &str, pinned: &[String]) -> Vec<ChatMessage> {
211	    let mut user = format!("Topic: {topic}\n\n");
212	    if !pinned.is_empty() {
213	        user.push_str(&format!(
214	            "Prioritize these pinned sources in the final report if their content is present in the verified draft below:\n{}\n\n",
215	            pinned.join("\n")
216	        ));
217	    }
218	    user.push_str(&format!("Verified draft:\n{verified_draft}"));
219	    vec![
220	        ChatMessage::text("system", WRITER_PROMPT),
