224	
225	use std::sync::Arc;
226	
227	use tokio::sync::mpsc;
228	
229	use crate::provider::openrouter::OpenRouter;
230	use crate::provider::{ChatParams, StreamEvent};
231	use crate::tools::ToolBox;
232	
233	use super::ResearchMsg;
234	
235	/// Send the `(session_id, space_id, space_name)` triple's stage update.
236	fn send_stage(
237	    tx: &mpsc::UnboundedSender<ResearchMsg>,
238	    ids: &(String, String, String),
239	    label: impl Into<String>,
240	    detail: impl Into<String>,
241	) {
242	    let _ = tx.send((
243	        ids.0.clone(),
244	        ids.1.clone(),
245	        ids.2.clone(),
246	        ResearchUpdate::Stage {
247	            label: label.into(),
248	            detail: detail.into(),
249	        },
250	    ));
251	}
252	
253	/// Every steer instruction queued since the last drain, without blocking —
254	/// `try_recv` until the channel is empty. Called at each round boundary so
255	/// a user's mid-flight `/steer` gets picked up as an extra searcher round.
256	pub(crate) async fn drain_steers(rx: &mut mpsc::UnboundedReceiver<String>) -> Vec<String> {
257	    let mut out = Vec::new();
258	    while let Ok(s) = rx.try_recv() {
259	        out.push(s);
260	    }
261	    out
262	}
263	
264	async fn complete_text(
265	    provider: &OpenRouter,
266	    model: &str,
267	    messages: Vec<ChatMessage>,
268	) -> Result<String, String> {
269	    provider
270	        .complete(model, messages)
271	        .await
272	        .map(|s| s.trim().to_string())
273	        .map_err(|e| e.to_string())
274	}
275	
276	async fn plan(
277	    provider: &OpenRouter,
278	    model: &str,
279	    topic: &str,
280	    known: &[String],
281	) -> Result<Vec<String>, String> {
282	    let text = complete_text(provider, model, planner_messages_with_context(topic, known)).await?;
283	    let qs = parse_subquestions(&text);
284	    if qs.is_empty() {
285	        return Err(format!(
286	            "planner returned no usable sub-questions (raw reply: {text:.200})"
287	        ));
288	    }
289	    Ok(qs)
290	}
291	
292	/// One Searcher agent: given a single sub-question, runs the normal
293	/// tool-loop (restricted to web_search/fetch_url/academic_search) and
294	/// returns its final prose findings (including its own "Sources:" citation
295	/// list). Never returns an `Err` — a dead search/fetch/model call becomes a
296	/// placeholder finding string so one bad sub-question can't sink the whole
297	/// pipeline.
298	///
299	/// Every `Status`/`ToolCall` event along the way is forwarded as a live
300	/// stage update under this searcher's own label (`searcher N/total`), so the
301	/// UI shows what it's actually doing (searching, fetching a URL, etc.) in
302	/// real time instead of going silent until it finishes.
303	#[allow(clippy::too_many_arguments)]
304	async fn run_searcher(
305	    provider: &OpenRouter,
306	    model: &str,
307	    sub_question: &str,
308	    toolbox: Arc<ToolBox>,
309	    tx: &mpsc::UnboundedSender<ResearchMsg>,
310	    ids: &(String, String, String),
311	    round: usize,
312	    idx: usize,
313	    total: usize,
314	) -> String {
315	    // Include the round in the identity so follow-up agents never overwrite
316	    // first-round activity rows that happen to have the same index.
317	    let label = format!("searcher r{round} {}/{total}", idx + 1);
318	    send_stage(
319	        tx,
320	        ids,
321	        &label,
322	        format!("working — investigating \"{sub_question}\""),
323	    );
324	    let messages = vec![
325	        ChatMessage::text("system", SEARCHER_PROMPT),
326	        ChatMessage::text("user", sub_question),
327	    ];
328	    let tools = toolbox.defs();
329	    let (mut rx, _abort) = provider.stream_chat(
330	        model.to_string(),
331	        messages,
332	        ChatParams::default(),
333	        tools,
334	        toolbox,
335	        RESEARCH_SEARCHER_MAX_ITERS,
336	    );
337	    let mut buf = String::new();
338	    while let Some(ev) = rx.recv().await {
339	        match ev {
340	            StreamEvent::Token(t) => buf.push_str(&t),
341	            StreamEvent::Status(s) => {
342	                send_stage(tx, ids, &label, format!("working — {s}"));
343	            }
344	            StreamEvent::ToolCall {
345	                name,
346	                arguments,
347	                result,
348	            } => {
349	                let summary = crate::app::tool_call_summary(&name, &arguments, &result);
350	                send_stage(tx, ids, &label, format!("working — {summary}"));
351	            }
352	            StreamEvent::Error(e) => {
353	                send_stage(tx, ids, &label, format!("error — {e}"));
354	                return format!("[search agent error on \"{sub_question}\": {e}]");
355	            }
356	            StreamEvent::Done => break,
357	            _ => {}
358	        }
359	    }
360	    let text = buf.trim();
361	    if text.is_empty() {
362	        send_stage(tx, ids, &label, "error — no findings returned");
363	        format!("[no findings for \"{sub_question}\"]")
364	    } else {
365	        send_stage(
366	            tx,
367	            ids,
368	            &label,
369	            format!("done — answered \"{sub_question}\""),
370	        );
371	        text.to_string()
372	    }
373	}
374	
375	/// Run the Verifier stage with a cache-only toolbox so it can check direct
376	/// quotes against exactly the pages searchers already gathered (never a
377	/// fresh fetch). Never returns an `Err` — returns whatever text accumulated
378	/// before the stream ended, or an empty string if it errored before
379	/// producing any. The caller falls back to the unverified draft when this
380	/// comes back empty, so verification failing must never blank out an
381	/// otherwise-good report.
382	async fn verify_with_quote_check(
383	    provider: &OpenRouter,
384	    model: &str,
385	    messages: Vec<ChatMessage>,
386	    cache_only_toolbox: Arc<ToolBox>,
387	    tx: &mpsc::UnboundedSender<ResearchMsg>,
388	    ids: &(String, String, String),
389	) -> String {
390	    let tools = cache_only_toolbox.defs();
391	    let (mut rx, _abort) = provider.stream_chat(
392	        model.to_string(),
393	        messages,
394	        ChatParams::default(),
395	        tools,
396	        cache_only_toolbox,
397	        RESEARCH_SEARCHER_MAX_ITERS,
398	    );
399	    let mut buf = String::new();
400	    while let Some(ev) = rx.recv().await {
401	        match ev {
402	            StreamEvent::Token(t) => buf.push_str(&t),
403	            StreamEvent::Status(s) => send_stage(tx, ids, "verifier", format!("working — {s}")),
404	            StreamEvent::ToolCall {
405	                name,
406	                arguments,
407	                result,
408	            } => {
409	                let summary = crate::app::tool_call_summary(&name, &arguments, &result);
410	                send_stage(tx, ids, "verifier", format!("working — {summary}"));
411	            }
412	            StreamEvent::Error(e) => {
413	                send_stage(tx, ids, "verifier", format!("error — {e}"));
414	                break;
415	            }
416	            StreamEvent::Done => break,
417	            _ => {}
418	        }
419	    }
420	    if !buf.trim().is_empty() {
421	        send_stage(tx, ids, "verifier", "done — source checks complete");
422	    }
423	    buf
424	}
425	
426	/// Fan out one Searcher per question in parallel, sending a running
427	/// `{done}/{total}` stage update as each finishes (in addition to each
428	/// searcher's own live per-tool-call feed). Order of the returned findings
429	/// doesn't matter (synthesis treats them as an unordered set).
430	async fn run_searchers(
431	    provider: &OpenRouter,
432	    model: &str,
433	    toolbox: &Arc<ToolBox>,
434	    questions: &[String],
435	    tx: &mpsc::UnboundedSender<ResearchMsg>,
436	    ids: &(String, String, String),
437	    round: usize,
438	) -> Vec<String> {
439	    let total = questions.len();
440	    send_stage(
441	        tx,
442	        ids,
443	        format!("search round {round}"),
444	        format!("working — 0/{total} agents complete"),
445	    );
446	    let mut set = tokio::task::JoinSet::new();
447	    for (idx, q) in questions.iter().cloned().enumerate() {
448	        let provider = provider.clone();
449	        let model = model.to_string();
450	        let toolbox = toolbox.clone();
451	        let tx = tx.clone();
452	        let ids = ids.clone();
453	        set.spawn(async move {
454	            run_searcher(&provider, &model, &q, toolbox, &tx, &ids, round, idx, total).await
455	        });
456	    }
457	    let mut done = 0usize;
458	    let mut findings = Vec::with_capacity(total);
459	    while let Some(res) = set.join_next().await {
460	        done += 1;
461	        send_stage(
462	            tx,
463	            ids,
464	            format!("search round {round}"),
465	            format!("working — {done}/{total} agents complete"),
466	        );
467	        findings.push(res.unwrap_or_else(|e| format!("[search agent panicked: {e}]")));
468	    }
469	    send_stage(
470	        tx,
471	        ids,
472	        format!("search round {round}"),
473	        format!("done — {done}/{total} agents complete"),
474	    );
475	    findings
476	}
477	
478	/// Run the full pipeline and send exactly one final `Done` on `tx` (the
479	/// caller's channel then closes naturally when this function returns and
480	/// `tx` is dropped).
481	pub(crate) async fn run_research(
482	    research_provider: OpenRouter,
483	    research_model: String,
484	    escalation_provider: OpenRouter,
485	    escalation_model: String,
486	    embedding_provider: OpenRouter,
487	    embedding_model: String,
488	    db_path: std::path::PathBuf,
489	    topic: String,
490	    gate_rx: Option<tokio::sync::oneshot::Receiver<Vec<String>>>,
491	    steer_rx: mpsc::UnboundedReceiver<String>,
492	    toolbox: Arc<ToolBox>,
493	    tx: mpsc::UnboundedSender<ResearchMsg>,
494	    session_id: String,
495	    space_id: String,
496	    space_name: String,
497	) {
498	    let known = local_known_chunks(
499	        &embedding_provider,
500	        &embedding_model,
501	        &db_path,
502	        &space_id,
503	        &topic,
504	    )
505	    .await;
506	    let ids = (session_id, space_id, space_name);
507	    let result = run_research_inner(
508	        &research_provider,
509	        &research_model,
510	        &escalation_provider,
511	        &escalation_model,
512	        &topic,
513	        &known,
514	        gate_rx,
515	        steer_rx,
516	        &db_path,
517	        &toolbox,
518	        &tx,
519	        &ids,
520	    )

