  1	//! Deep research: a background multi-agent pipeline triggered by `/research`.
  2	//! Every stage but the Searcher fan-out is a single `Provider::complete`
  3	//! call; parsing/prompt-building here is pure and unit tested. The async
  4	//! orchestration (Task 9) calls real network endpoints and is exercised
  5	//! manually, like every other network-calling background job in this
  6	//! codebase (`maybe_generate_title`, image description, embedding).
  7	
  8	use crate::provider::ChatMessage;
  9	
 10	/// A background research pipeline update: a phase label (+ progress detail),
 11	/// the Planner's sub-questions awaiting approval, or the final report/error.
 12	pub(crate) enum ResearchUpdate {
 13	    /// Successive updates within one stage share a `label` so the UI/db
 14	    /// replace one row in place instead of appending per tick.
 15	    Stage {
 16	        label: String,
 17	        detail: String,
 18	    },
 19	    /// The Planner finished; the pipeline is paused awaiting approve/edit
 20	    /// (or its 60s auto-continue timeout).
 21	    PlanReady {
 22	        questions: Vec<String>,
 23	    },
 24	    Done(std::result::Result<String, String>),
 25	}
 26	
 27	/// Hard cap on Planner-generated sub-questions per outer round.
 28	const MAX_SUBQUESTIONS: usize = 6;
 29	/// Tool-call budget for a single Searcher agent — a few search→fetch hops,
 30	/// not a whole interactive conversation's worth.
 31	pub(crate) const RESEARCH_SEARCHER_MAX_ITERS: usize = 6;
 32	
 33	const PLANNER_PROMPT: &str = "You are the planning stage of an automated research pipeline. Given a research topic, decompose it into 3 to 6 focused sub-questions that together cover the topic thoroughly (different angles: definitions, current state, evidence/data, controversies, practical implications — whichever apply). Respond with ONLY a JSON array of strings, no prose, no markdown fences. Example: [\"question one\", \"question two\"]. Note: searcher agents handling scholarly sub-questions can call academic_search (Semantic Scholar) in addition to web_search, so peer-reviewed angles are fair game.";
 34	
 35	pub(crate) const SEARCHER_PROMPT: &str = "You are a research searcher agent. You will be given one focused sub-question. Use the web_search and fetch_url tools to investigate it thoroughly: search, then fetch and read the most promising pages, and search again with new terms you learn from them if needed. When you have enough to answer well, write a concise findings summary (a few paragraphs, prose, no headers) that directly answers the sub-question, citing sources inline as [n]. End your answer with a line starting exactly with 'Sources:' followed by the numbered list of URLs you used, one per line, matching your [n] citations. Prefer sources from domains you have not already cited — diverse sources make a stronger report.";
 36	
 37	const SYNTHESIZER_PROMPT: &str = "You are the synthesis stage of a research pipeline. You'll be given the original topic and findings from several searcher agents, each already citing their own sources. Combine them into a single coherent draft report on the topic: organize by theme (not by sub-question), resolve obvious overlaps, keep every citation but you may renumber them consistently as you merge. Do not invent facts not present in the findings. Output the draft report in markdown, no preamble.";
 38	
 39	const CRITIC_PROMPT: &str = "You are the critic stage of a research pipeline. Given the original topic and a draft report, decide if it's ready. Respond in exactly one of these forms:\n- the single word SATISFIED, if the draft thoroughly covers the topic with no notable gaps or contradictions.\n- GAPS: followed by a newline-separated bullet list (each line starting with '- ') of specific missing sub-topics or unanswered angles, each phrased as a searchable question.\n- CONTRADICTION: followed by one line describing a specific factual contradiction between sources in the draft that isn't resolved.\nUse CONTRADICTION only for an actual conflict between sources, not a missing angle — missing angles are always GAPS. Respond with nothing else.";
 40	
 41	const ESCALATION_PROMPT: &str = "You are resolving a contradiction found in a research draft. You are given the topic, the draft, the full set of source findings gathered so far, and a description of the contradiction. Determine which claim the evidence better supports (or that both apply in different contexts) and write one paragraph resolving it, citing the [n] sources involved. Output only that paragraph.";
 42	
 43	const VERIFIER_PROMPT: &str = "You are the verifier stage. Given the topic, the gathered source findings (with their citations), and a draft report, check every factual claim in the draft against the source findings. Rewrite the draft unchanged except: (1) remove or mark with '⚠ unverifiable:' any claim not actually supported by the gathered findings; (2) immediately after a claim's citations, judge its confidence from citation count and cross-source agreement and, only for low or medium confidence, append the tag ‹low› or ‹med› right after the citation (high confidence is the default and stays untagged — do not tag it). Output the corrected draft in markdown, nothing else. You have a fetch_url tool restricted to already-cached pages: use it to check any direct quote in the draft against the cached source text, and mark a quote that doesn't actually match with '‹unverified quote›' immediately after it.";
 44	
 45	const WRITER_PROMPT: &str = "You are the final writer stage. Given the topic and a verified draft report (with inline [n] citations and prose from earlier stages, possibly including a contradiction-resolution paragraph to fold in), produce the final report: clean markdown, a short introductory paragraph, organized sections with headers, inline [n] citations preserved/renumbered consistently, and a trailing '## Sources' section listing every cited URL as 'n. url'. Output only the final report markdown, nothing else — it will be saved and shown to the user as-is.";
 46	
 47	/// The Critic stage's structured decision.
 48	#[derive(Debug, Clone, PartialEq)]
 49	pub(crate) enum Critique {
 50	    Satisfied,
 51	    Gaps(Vec<String>),
 52	    Contradiction(String),
 53	}
 54	
 55	/// Parse the Planner's raw reply into sub-questions: a JSON string array, or
 56	/// (if the model didn't follow instructions) a best-effort line-by-line
 57	/// fallback stripping bullet/number prefixes. Always capped at
 58	/// `MAX_SUBQUESTIONS`.
 59	pub(crate) fn parse_subquestions(text: &str) -> Vec<String> {
 60	    let trimmed = text
 61	        .trim()
 62	        .trim_start_matches("```json")
 63	        .trim_start_matches("```")
 64	        .trim_end_matches("```")
 65	        .trim();
 66	    if let Ok(v) = serde_json::from_str::<Vec<String>>(trimmed) {
 67	        return v
 68	            .into_iter()
 69	            .map(|s| s.trim().to_string())
 70	            .filter(|s| !s.is_empty())
 71	            .take(MAX_SUBQUESTIONS)
 72	            .collect();
 73	    }
 74	    trimmed
 75	        .lines()
 76	        .map(strip_list_prefix)
 77	        .filter(|l| !l.is_empty())
 78	        .take(MAX_SUBQUESTIONS)
 79	        .collect()
 80	}
 81	
 82	/// Strip a leading `-`, `*`, or `N.`/`N)` list-item marker, if present.
 83	fn strip_list_prefix(line: &str) -> String {
 84	    let s = line.trim().trim_start_matches(['-', '*']).trim();
 85	    let digits_end = s.find(|c: char| !c.is_ascii_digit()).unwrap_or(0);
 86	    if digits_end > 0 {
 87	        if let Some(rest) = s[digits_end..].strip_prefix(['.', ')']) {
 88	            return rest.trim().to_string();
 89	        }
 90	    }
 91	    s.to_string()
 92	}
 93	
 94	/// Parse the user-edited plan (one sub-question per line, same bullet/number
 95	/// tolerance as the Planner's own fallback parser) back into a list.
 96	pub(crate) fn parse_plan_edit(text: &str) -> Vec<String> {
 97	    text.lines()
 98	        .map(strip_list_prefix)
 99	        .filter(|l| !l.is_empty())
100	        .take(MAX_SUBQUESTIONS)
101	        .collect()
102	}
103	
104	/// Parse the Critic's raw reply into a `Critique`. Anything that doesn't
105	/// match one of the three expected shapes is treated as `Satisfied` — an
106	/// unparseable critique shouldn't loop the pipeline forever on garbage.
107	pub(crate) fn parse_critique(text: &str) -> Critique {
108	    let t = text.trim();
109	    if t.eq_ignore_ascii_case("SATISFIED") {
110	        return Critique::Satisfied;
111	    }
112	    if let Some(rest) = t.strip_prefix("CONTRADICTION:") {
113	        let desc = rest.trim();
114	        if !desc.is_empty() {
115	            return Critique::Contradiction(desc.to_string());
116	        }
117	    }
118	    if let Some(rest) = t.strip_prefix("GAPS:") {
119	        let gaps: Vec<String> = rest
120	            .lines()
121	            .map(str::trim)
122	            .filter_map(|l| l.strip_prefix('-'))
123	            .map(|l| l.trim().to_string())
124	            .filter(|l| !l.is_empty())
125	            .take(MAX_SUBQUESTIONS)
126	            .collect();
127	        if !gaps.is_empty() {
128	            return Critique::Gaps(gaps);
129	        }
130	    }
131	    Critique::Satisfied
132	}
133	
134	/// The Planner's request, with any locally-known context (chunks from the
135	/// space's own files, semantically matched to the topic) framed as "already
136	/// known — plan sub-questions for the gaps".
137	fn planner_messages_with_context(topic: &str, known: &[String]) -> Vec<ChatMessage> {
138	    let user = if known.is_empty() {
139	        topic.to_string()
140	    } else {
141	        format!(
142	            "Topic: {topic}\n\nAlready known (from the user's own files) — plan sub-questions \
143	             for the gaps, not what's already covered:\n{}",
144	            known.join("\n\n")
145	        )
146	    };
147	    vec![
148	        ChatMessage::text("system", PLANNER_PROMPT),
149	        ChatMessage::text("user", user),
150	    ]
151	}
152	
153	fn synthesizer_messages(topic: &str, findings: &[String], pinned: &[String]) -> Vec<ChatMessage> {
154	    let body = findings
155	        .iter()
156	        .enumerate()
157	        .map(|(i, f)| format!("--- Searcher {} findings ---\n{f}", i + 1))
158	        .collect::<Vec<_>>()
159	        .join("\n\n");
160	    let mut user = format!("Topic: {topic}\n\n");
161	    if !pinned.is_empty() {
162	        user.push_str(&format!(
163	            "Prioritize these pinned sources in the synthesis if their content is present in the findings below:\n{}\n\n",
164	            pinned.join("\n")
165	        ));
166	    }
167	    user.push_str(&body);
168	    vec![
169	        ChatMessage::text("system", SYNTHESIZER_PROMPT),
170	        ChatMessage::text("user", user),
171	    ]
172	}
173	
174	fn critic_messages(topic: &str, draft: &str) -> Vec<ChatMessage> {
175	    vec![
176	        ChatMessage::text("system", CRITIC_PROMPT),
177	        ChatMessage::text("user", format!("Topic: {topic}\n\nDraft:\n{draft}")),
178	    ]
179	}
180	
181	fn escalation_messages(
182	    topic: &str,
183	    draft: &str,
184	    findings: &[String],
185	    contradiction: &str,
186	) -> Vec<ChatMessage> {
187	    let body = findings.join("\n\n");
188	    vec![
189	        ChatMessage::text("system", ESCALATION_PROMPT),
190	        ChatMessage::text(
191	            "user",
192	            format!(
193	                "Topic: {topic}\n\nContradiction: {contradiction}\n\nDraft:\n{draft}\n\nSource findings:\n{body}"
194	            ),
195	        ),
196	    ]
197	}
198	
199	fn verifier_messages(topic: &str, draft: &str, findings: &[String]) -> Vec<ChatMessage> {
200	    let body = findings.join("\n\n");
201	    vec![
202	        ChatMessage::text("system", VERIFIER_PROMPT),
203	        ChatMessage::text(
204	            "user",
205	            format!("Topic: {topic}\n\nSource findings:\n{body}\n\nDraft:\n{draft}"),
206	        ),
207	    ]
208	}
