236	fn send_stage(
237	    tx: &mpsc::UnboundedSender<ResearchMsg>,
238	    ids: &(String, String, String),
239	    label: impl Into<String>,
240	    detail: impl Into<String>,
241	) {
242	    let _ = tx.send((
243	        ids.0.clone(),
244	        ids.1.clone(),
245	        ids.2.clone(),
