253	/// Every steer instruction queued since the last drain, without blocking —
254	/// `try_recv` until the channel is empty. Called at each round boundary so
255	/// a user's mid-flight `/steer` gets picked up as an extra searcher round.
256	pub(crate) async fn drain_steers(rx: &mut mpsc::UnboundedReceiver<String>) -> Vec<String> {
257	    let mut out = Vec::new();
258	    while let Ok(s) = rx.try_recv() {
259	        out.push(s);
260	    }
261	    out
262	}
