292	/// One Searcher agent: given a single sub-question, runs the normal
293	/// tool-loop (restricted to web_search/fetch_url/academic_search) and
294	/// returns its final prose findings (including its own "Sources:" citation
295	/// list). Never returns an `Err` — a dead search/fetch/model call becomes a
296	/// placeholder finding string so one bad sub-question can't sink the whole
297	/// pipeline.
298	///
299	/// Every `Status`/`ToolCall` event along the way is forwarded as a live
300	/// stage update under this searcher's own label (`searcher N/total`), so the
301	/// UI shows what it's actually doing (searching, fetching a URL, etc.) in
302	/// real time instead of going silent until it finishes.
303	#[allow(clippy::too_many_arguments)]
304	async fn run_searcher(
305	    provider: &OpenRouter,
306	    model: &str,
307	    sub_question: &str,
308	    toolbox: Arc<ToolBox>,
309	    tx: &mpsc::UnboundedSender<ResearchMsg>,
310	    ids: &(String, String, String),
311	    round: usize,
312	    idx: usize,
313	    total: usize,
314	) -> String {
315	    // Include the round in the identity so follow-up agents never overwrite
316	    // first-round activity rows that happen to have the same index.
317	    let label = format!("searcher r{round} {}/{total}", idx + 1);
318	    send_stage(
319	        tx,
320	        ids,
321	        &label,
322	        format!("working — investigating \"{sub_question}\""),
323	    );
324	    let messages = vec![
325	        ChatMessage::text("system", SEARCHER_PROMPT),
326	        ChatMessage::text("user", sub_question),
327	    ];
328	    let tools = toolbox.defs();
329	    let (mut rx, _abort) = provider.stream_chat(
330	        model.to_string(),
331	        messages,
332	        ChatParams::default(),
333	        tools,
334	        toolbox,
335	        RESEARCH_SEARCHER_MAX_ITERS,
336	    );
337	    let mut buf = String::new();
338	    while let Some(ev) = rx.recv().await {
339	        match ev {
340	            StreamEvent::Token(t) => buf.push_str(&t),
341	            StreamEvent::Status(s) => {
342	                send_stage(tx, ids, &label, format!("working — {s}"));
343	            }
344	            StreamEvent::ToolCall {
345	                name,
346	                arguments,
347	                result,
348	            } => {
349	                let summary = crate::app::tool_call_summary(&name, &arguments, &result);
350	                send_stage(tx, ids, &label, format!("working — {summary}"));
351	            }
352	            StreamEvent::Error(e) => {
353	                send_stage(tx, ids, &label, format!("error — {e}"));
354	                return format!("[search agent error on \"{sub_question}\": {e}]");
355	            }
356	            StreamEvent::Done => break,
357	            _ => {}
358	        }
359	    }
360	    let text = buf.trim();
361	    if text.is_empty() {
362	        send_stage(tx, ids, &label, "error — no findings returned");
363	        format!("[no findings for \"{sub_question}\"]")
364	    } else {
365	        send_stage(
366	            tx,
367	            ids,
368	            &label,
369	            format!("done — answered \"{sub_question}\""),
370	        );
371	        text.to_string()
372	    }
373	}
