375	/// Run the Verifier stage with a cache-only toolbox so it can check direct
376	/// quotes against exactly the pages searchers already gathered (never a
377	/// fresh fetch). Never returns an `Err` — returns whatever text accumulated
378	/// before the stream ended, or an empty string if it errored before
379	/// producing any. The caller falls back to the unverified draft when this
380	/// comes back empty, so verification failing must never blank out an
381	/// otherwise-good report.
382	async fn verify_with_quote_check(
383	    provider: &OpenRouter,
384	    model: &str,
385	    messages: Vec<ChatMessage>,
386	    cache_only_toolbox: Arc<ToolBox>,
387	    tx: &mpsc::UnboundedSender<ResearchMsg>,
388	    ids: &(String, String, String),
389	) -> String {
390	    let tools = cache_only_toolbox.defs();
391	    let (mut rx, _abort) = provider.stream_chat(
392	        model.to_string(),
393	        messages,
394	        ChatParams::default(),
395	        tools,
396	        cache_only_toolbox,
397	        RESEARCH_SEARCHER_MAX_ITERS,
398	    );
399	    let mut buf = String::new();
400	    while let Some(ev) = rx.recv().await {
401	        match ev {
402	            StreamEvent::Token(t) => buf.push_str(&t),
403	            StreamEvent::Status(s) => send_stage(tx, ids, "verifier", format!("working — {s}")),
404	            StreamEvent::ToolCall {
405	                name,
406	                arguments,
407	                result,
408	            } => {
409	                let summary = crate::app::tool_call_summary(&name, &arguments, &result);
410	                send_stage(tx, ids, "verifier", format!("working — {summary}"));
411	            }
412	            StreamEvent::Error(e) => {
413	                send_stage(tx, ids, "verifier", format!("error — {e}"));
414	                break;
415	            }
416	            StreamEvent::Done => break,
417	            _ => {}
418	        }
419	    }
420	    if !buf.trim().is_empty() {
421	        send_stage(tx, ids, "verifier", "done — source checks complete");
422	    }
423	    buf
424	}
