 525	/// Top-k chunks from the space's files already relevant to `topic`, for the
 526	/// Planner's "already known" context — silently empty when embeddings are
 527	/// unconfigured, embedding fails, or the space has no files (never blocks
 528	/// `/research` on any of those).
 529	async fn local_known_chunks(
 530	    provider: &OpenRouter,
 531	    embedding_model: &str,
 532	    db_path: &std::path::Path,
 533	    space_id: &str,
 534	    topic: &str,
 535	) -> Vec<String> {
 536	    if embedding_model.trim().is_empty() {
 537	        return Vec::new();
 538	    }
 539	    let Ok(mut vecs) = provider
 540	        .embed(embedding_model, vec![topic.to_string()])
 541	        .await
 542	    else {
 543	        return Vec::new();
 544	    };
 545	    if vecs.is_empty() {
 546	        return Vec::new();
 547	    }
 548	    let query = vecs.remove(0);
 549	    let Ok(conn) = rusqlite::Connection::open(db_path) else {
 550	        return Vec::new();
 551	    };
 552	    crate::db::semantic_chunks(&conn, space_id, &query, 5)
 553	        .map(|hits| {
 554	            hits.into_iter()
 555	                .map(|(name, loc, text, _)| format!("{name} ({loc}): {text}"))
 556	                .collect()
 557	        })
 558	        .unwrap_or_default()
 559	}
