 561	#[allow(clippy::too_many_arguments)]
 562	async fn run_research_inner(
 563	    research_provider: &OpenRouter,
 564	    research_model: &str,
 565	    escalation_provider: &OpenRouter,
 566	    escalation_model: &str,
 567	    topic: &str,
 568	    known: &[String],
 569	    gate_rx: Option<tokio::sync::oneshot::Receiver<Vec<String>>>,
 570	    mut steer_rx: mpsc::UnboundedReceiver<String>,
 571	    db_path: &std::path::Path,
 572	    toolbox: &Arc<ToolBox>,
 573	    tx: &mpsc::UnboundedSender<ResearchMsg>,
 574	    ids: &(String, String, String),
 575	) -> Result<String, String> {
 576	    send_stage(
 577	        tx,
 578	        ids,
 579	        "planner",
 580	        "working — decomposing the topic into focused questions",
 581	    );
 582	    let mut questions = match plan(research_provider, research_model, topic, known).await {
 583	        Ok(questions) => questions,
 584	        Err(e) => {
 585	            send_stage(tx, ids, "planner", format!("error — {e}"));
 586	            return Err(e);
 587	        }
 588	    };
 589	    send_stage(
 590	        tx,
 591	        ids,
 592	        "planner",
 593	        format!("done — proposed {} questions", questions.len()),
 594	    );
 595	
 596	    // Plan-approval gate: show the sub-questions and wait for approve/edit,
 597	    // auto-continuing after 60s so a backgrounded session never hangs.
 598	    if let Some(gate_rx) = gate_rx {
 599	        let _ = tx.send((
 600	            ids.0.clone(),
 601	            ids.1.clone(),
 602	            ids.2.clone(),
 603	            ResearchUpdate::PlanReady {
 604	                questions: questions.clone(),
 605	            },
 606	        ));
 607	        questions = match tokio::time::timeout(std::time::Duration::from_secs(60), gate_rx).await {
 608	            Ok(Ok(edited)) if !edited.is_empty() => edited,
 609	            // Timeout, dropped sender, or an empty edit — continue as planned.
 610	            _ => questions,
 611	        };
 612	    }
 613	
 614	    let pinned = rusqlite::Connection::open(db_path)
 615	        .ok()
 616	        .and_then(|conn| crate::db::pinned_urls(&conn, &ids.0).ok())
 617	        .unwrap_or_default();
 618	
 619	    let mut findings = run_searchers(
 620	        research_provider,
 621	        research_model,
 622	        toolbox,
 623	        &questions,
 624	        tx,
 625	        ids,
 626	        1,
 627	    )
 628	    .await;
 629	    persist_session_sources(db_path, &ids.0, &findings);
 630	
 631	    let steers = drain_steers(&mut steer_rx).await;
 632	    if !steers.is_empty() {
 633	        for s in &steers {
 634	            send_stage(tx, ids, "steer", s.clone());
 635	        }
 636	        let steered = run_searchers(
 637	            research_provider,
 638	            research_model,
 639	            toolbox,
 640	            &steers,
 641	            tx,
 642	            ids,
 643	            1,
 644	        )
 645	        .await;
 646	        persist_session_sources(db_path, &ids.0, &steered);
 647	        findings.extend(steered);
 648	    }
 649	
 650	    send_stage(
 651	        tx,
 652	        ids,
 653	        "synthesizer",
 654	        format!("working — combining {} agent findings", findings.len()),
 655	    );
 656	    let mut draft = complete_text(
 657	        research_provider,
 658	        research_model,
 659	        synthesizer_messages(topic, &crate::tools::dedup_source_lines(&findings), &pinned),
 660	    )
 661	    .await?;
 662	    send_stage(tx, ids, "synthesizer", "done — draft assembled");
 663	
 664	    send_stage(
 665	        tx,
 666	        ids,
 667	        "critic",
 668	        "working — checking coverage and contradictions",
 669	    );
 670	    let mut critique = parse_critique(
 671	        &complete_text(
 672	            research_provider,
 673	            research_model,
 674	            critic_messages(topic, &draft),
 675	        )
 676	        .await?,
 677	    );
 678	    let critic_detail = match &critique {
 679	        Critique::Satisfied => "done — draft is sufficiently complete".to_string(),
 680	        Critique::Gaps(gaps) => format!("done — found {} coverage gaps", gaps.len()),
 681	        Critique::Contradiction(_) => "done — found a source contradiction".to_string(),
 682	    };
 683	    send_stage(tx, ids, "critic", critic_detail);
 684	
 685	    if let Critique::Gaps(gaps) = &critique {
 686	        let more =
 687	            run_searchers(research_provider, research_model, toolbox, gaps, tx, ids, 2).await;
 688	        persist_session_sources(db_path, &ids.0, &more);
 689	        findings.extend(more);
 690	
 691	        let steers = drain_steers(&mut steer_rx).await;
 692	        if !steers.is_empty() {
 693	            for s in &steers {
 694	                send_stage(tx, ids, "steer", s.clone());
 695	            }
 696	            let steered = run_searchers(
 697	                research_provider,
 698	                research_model,
 699	                toolbox,
 700	                &steers,
 701	                tx,
 702	                ids,
 703	                2,
 704	            )
 705	            .await;
 706	            persist_session_sources(db_path, &ids.0, &steered);
 707	            findings.extend(steered);
 708	        }
 709	
 710	        send_stage(
 711	            tx,
 712	            ids,
 713	            "synthesizer r2",
 714	            "working — merging follow-up findings",
 715	        );
 716	        draft = complete_text(
 717	            research_provider,
 718	            research_model,
 719	            synthesizer_messages(topic, &crate::tools::dedup_source_lines(&findings), &pinned),
 720	        )
 721	        .await?;
 722	        send_stage(tx, ids, "synthesizer r2", "done — revised draft assembled");
 723	        send_stage(
 724	            tx,
 725	            ids,
 726	            "critic r2",
 727	            "working — reviewing the revised draft",
 728	        );
 729	        critique = parse_critique(
 730	            &complete_text(
 731	                research_provider,
 732	                research_model,
 733	                critic_messages(topic, &draft),
 734	            )
 735	            .await?,
 736	        );
 737	        let detail = match &critique {
 738	            Critique::Satisfied => "done — revised draft is complete".to_string(),
 739	            Critique::Gaps(gaps) => format!("done — {} gaps remain", gaps.len()),
 740	            Critique::Contradiction(_) => "done — contradiction remains".to_string(),
 741	        };
 742	        send_stage(tx, ids, "critic r2", detail);
 743	    }
 744	
 745	    if let Critique::Contradiction(desc) = &critique {
 746	        send_stage(
 747	            tx,
 748	            ids,
 749	            "resolver",
 750	            "working — reconciling conflicting source claims",
 751	        );
 752	        let resolution = complete_text(
 753	            escalation_provider,
 754	            escalation_model,
 755	            escalation_messages(topic, &draft, &findings, desc),
 756	        )
 757	        .await?;
 758	        draft.push_str("\n\n");
 759	        draft.push_str(&resolution);
 760	        send_stage(tx, ids, "resolver", "done — contradiction reconciled");
 761	    }
 762	
 763	    send_stage(
 764	        tx,
 765	        ids,
 766	        "verifier",
 767	        "working — checking claims, citations, and direct quotes",
 768	    );
 769	    let verify_toolbox = Arc::new(
 770	        ToolBox::research(
 771	            None,
 772	            None,
 773	            "auto".to_string(),
 774	            Vec::new(),
 775	            Some(db_path.to_path_buf()),
 776	        )
 777	        .cache_only(),
 778	    );
 779	    let verified_raw = verify_with_quote_check(
 780	        research_provider,
 781	        research_model,
 782	        verifier_messages(topic, &draft, &findings),
 783	        verify_toolbox,
 784	        tx,
 785	        ids,
 786	    )
 787	    .await;
 788	    let verified = if verified_raw.trim().is_empty() {
 789	        draft.clone()
 790	    } else {
 791	        verified_raw
 792	    };
 793	
 794	    send_stage(
 795	        tx,
 796	        ids,
 797	        "writer",
 798	        "working — polishing structure and citations",
 799	    );
 800	    match complete_text(
 801	        research_provider,
 802	        research_model,
 803	        writer_messages(topic, &verified, &pinned),
 804	    )
 805	    .await
 806	    {
 807	        Ok(report) => {
 808	            send_stage(tx, ids, "writer", "done — final report ready");
 809	            Ok(report)
 810	        }
 811	        Err(e) => {
 812	            send_stage(tx, ids, "writer", format!("error — {e}"));
 813	            Err(e)
 814	        }
 815	    }
 816	}
