 818	/// Link every URL cited in `findings` into the session's source bundle
 819	/// (they're already in `web_cache` from `fetch_url`'s write-through). Best
 820	/// effort — a failed write never disturbs the pipeline.
 821	fn persist_session_sources(db_path: &std::path::Path, session_id: &str, findings: &[String]) {
 822	    let url_norms = crate::tools::cited_url_norms(findings);
 823	    if url_norms.is_empty() {
 824	        return;
 825	    }
 826	    if let Ok(conn) = rusqlite::Connection::open(db_path) {
 827	        let _ = crate::db::add_session_sources(&conn, session_id, &url_norms);
 828	    }
 829	}
