 831	impl super::App {
 832	    /// `/research <topic>`: run the multi-agent research pipeline in a new
 833	    /// background session. One job at a time. `/research! <topic>` skips the
 834	    /// plan-approval gate.
 835	    pub(crate) fn start_research(&mut self, topic: &str) {
 836	        self.start_research_with_gate(topic, true)
 837	    }
 838	
 839	    /// `/steer <text>`: queue an extra instruction for the running research
 840	    /// job, picked up at the next round boundary. No-op with a status message
 841	    /// if no research job is running.
 842	    pub(crate) fn steer_research(&mut self, text: &str) {
 843	        if text.is_empty() {
 844	            self.status = "usage: /steer <what to also look into>".to_string();
 845	            return;
 846	        }
