 859	    /// still lets you bail or edit before searchers run.
 860	    pub(crate) fn start_research_from_chat(&mut self) {
 861	        if self.research_topic_rx.is_some() {
 862	            self.status = "already scoping a topic from this chat…".to_string();
 863	            return;
 864	        }
 865	        if self.research_rx.is_some() {
 866	            self.status = "a research job is already running".to_string();
 867	            return;
 868	        }
 869	        let Some(model) = self.current_model.clone() else {
 870	            self.status = "no model configured — set one in /login or /model".to_string();
 871	            return;
 872	        };
 873	        let Some((provider, raw_model)) = self.resolve_model_backend(&model) else {
 874	            self.status = format!("model backend unavailable: {model} — pick another with /model");
 875	            return;
 876	        };
 877	        let convo: String = self
 878	            .messages
 879	            .iter()
 880	            .filter(|m| m.role == "user" || m.role == "assistant")
 880	            .filter(|m| m.role == "user" || m.role == "assistant")
 881	            .rev()
 882	            .take(20)
 883	            .collect::<Vec<_>>()
 884	            .into_iter()
 885	            .rev()
 886	            .map(|m| {
 887	                format!(
 888	                    "{}: {}",
 889	                    m.role,
 890	                    m.content.chars().take(500).collect::<String>()
 891	                )
 892	            })
 893	            .collect::<Vec<_>>()
 894	            .join("\n");
 895	        if convo.trim().is_empty() {
