373	/// Run the Verifier stage with a cache-only toolbox so it can check direct
374	/// quotes against exactly the pages searchers already gathered (never a
375	/// fresh fetch). Never returns an `Err` — returns whatever text accumulated
376	/// before the stream ended, or an empty string if it errored before
377	/// producing any. The caller falls back to the unverified draft when this
378	/// comes back empty, so verification failing must never blank out an
379	/// otherwise-good report.
380	async fn verify_with_quote_check(
381	    provider: &OpenRouter,
382	    model: &str,
383	    messages: Vec<ChatMessage>,
384	    cache_only_toolbox: Arc<ToolBox>,
385	) -> String {
386	    let tools = cache_only_toolbox.defs();
387	    let (mut rx, _abort) = provider.stream_chat(
388	        model.to_string(),
389	        messages,
390	        ChatParams::default(),
391	        tools,
392	        cache_only_toolbox,
393	        RESEARCH_SEARCHER_MAX_ITERS,
394	    );
395	    let mut buf = String::new();
396	    while let Some(ev) = rx.recv().await {
397	        match ev {
398	            StreamEvent::Token(t) => buf.push_str(&t),
399	            StreamEvent::Done | StreamEvent::Error(_) => break,
400	            _ => {}
401	        }
402	    }
403	    buf
404	}
