416	    ids: &(String, String, String),
417	    round: usize,
418	) -> Vec<String> {
419	    let total = questions.len();
420	    let mut set = tokio::task::JoinSet::new();
421	    for (idx, q) in questions.iter().cloned().enumerate() {
422	        let provider = provider.clone();
423	        let model = model.to_string();
424	        let toolbox = toolbox.clone();
425	        let tx = tx.clone();
426	        let ids = ids.clone();
427	        set.spawn(async move {
428	            run_searcher(&provider, &model, &q, toolbox, &tx, &ids, round, idx, total).await
429	        });
430	    }
431	    let mut done = 0usize;
432	    let mut findings = Vec::with_capacity(total);
433	    while let Some(res) = set.join_next().await {
434	        done += 1;
435	        send_stage(
436	            tx,
437	            ids,
438	            "searching",
439	            format!("round {round}, {done}/{total} done"),
440	        );
441	        findings.push(res.unwrap_or_else(|e| format!("[search agent panicked: {e}]")));
442	    }
443	    findings
444	}
