674	    /// `/research <topic>`: run the multi-agent research pipeline in a new
675	    /// background session. One job at a time. `/research! <topic>` skips the
676	    /// plan-approval gate.
677	    pub(crate) fn start_research(&mut self, topic: &str) {
678	        self.start_research_with_gate(topic, true)
679	    }
