292	/// One Searcher agent: given a single sub-question, runs the normal
293	/// tool-loop (restricted to web_search/fetch_url/academic_search) and
294	/// returns its final prose findings (including its own "Sources:" citation
295	/// list). Never returns an `Err` — a dead search/fetch/model call becomes a
296	/// placeholder finding string so one bad sub-question can't sink the whole
297	/// pipeline.
298	///
299	/// Every `Status`/`ToolCall` event along the way is forwarded as a live
300	/// stage update under this searcher's own label (`searcher N/total`), so the
301	/// UI shows what it's actually doing (searching, fetching a URL, etc.) in
302	/// real time instead of going silent until it finishes.
303	#[allow(clippy::too_many_arguments)]
304	async fn run_searcher(
305	    provider: &OpenRouter,
306	    model: &str,
307	    sub_question: &str,
308	    toolbox: Arc<ToolBox>,
309	    tx: &mpsc::UnboundedSender<ResearchMsg>,
310	    ids: &(String, String, String),
311	    round: usize,
312	    idx: usize,
313	    total: usize,
314	) -> String {
315	    let label = format!("searcher {}/{total}", idx + 1);
316	    send_stage(
317	        tx,
318	        ids,
319	        &label,
320	        format!("round {round}: \"{sub_question}\" — starting…"),
321	    );
322	    let messages = vec![
323	        ChatMessage::text("system", SEARCHER_PROMPT),
324	        ChatMessage::text("user", sub_question),
325	    ];
326	    let tools = toolbox.defs();
327	    let (mut rx, _abort) = provider.stream_chat(
328	        model.to_string(),
329	        messages,
330	        ChatParams::default(),
331	        tools,
332	        toolbox,
333	        RESEARCH_SEARCHER_MAX_ITERS,
334	    );
335	    let mut buf = String::new();
336	    while let Some(ev) = rx.recv().await {
337	        match ev {
338	            StreamEvent::Token(t) => buf.push_str(&t),
339	            StreamEvent::Status(s) => {
340	                send_stage(
341	                    tx,
342	                    ids,
343	                    &label,
344	                    format!("round {round}: \"{sub_question}\" — {s}"),
345	                );
346	            }
347	            StreamEvent::ToolCall {
348	                name, arguments, ..
349	            } => {
350	                let arg_summary: String = arguments.chars().take(80).collect();
351	                send_stage(
352	                    tx,
353	                    ids,
354	                    &label,
355	                    format!("round {round}: \"{sub_question}\" — used {name}({arg_summary})"),
356	                );
357	            }
358	            StreamEvent::Error(e) => {
359	                return format!("[search agent error on \"{sub_question}\": {e}]");
360	            }
361	            StreamEvent::Done => break,
362	            _ => {}
363	        }
364	    }
365	    let text = buf.trim();
366	    if text.is_empty() {
367	        format!("[no findings for \"{sub_question}\"]")
368	    } else {
369	        text.to_string()
370	    }
371	}
