406	/// Fan out one Searcher per question in parallel, sending a running
407	/// `{done}/{total}` stage update as each finishes (in addition to each
408	/// searcher's own live per-tool-call feed). Order of the returned findings
409	/// doesn't matter (synthesis treats them as an unordered set).
410	async fn run_searchers(
411	    provider: &OpenRouter,
412	    model: &str,
413	    toolbox: &Arc<ToolBox>,
414	    questions: &[String],
415	    tx: &mpsc::UnboundedSender<ResearchMsg>,
416	    ids: &(String, String, String),
417	    round: usize,
418	) -> Vec<String> {
419	    let total = questions.len();
420	    let mut set = tokio::task::JoinSet::new();
421	    for (idx, q) in questions.iter().cloned().enumerate() {
422	        let provider = provider.clone();
423	        let model = model.to_string();
424	        let toolbox = toolbox.clone();
425	        let tx = tx.clone();
426	        let ids = ids.clone();
427	        set.spawn(async move {
428	            run_searcher(&provider, &model, &q, toolbox, &tx, &ids, round, idx, total).await
429	        });
430	    }
431	    let mut done = 0usize;
432	    let mut findings = Vec::with_capacity(total);
433	    while let Some(res) = set.join_next().await {
434	        done += 1;
435	        send_stage(
436	            tx,
437	            ids,
438	            "searching",
439	            format!("round {round}, {done}/{total} done"),
440	        );
441	        findings.push(res.unwrap_or_else(|e| format!("[search agent panicked: {e}]")));
442	    }
443	    findings
444	}
445	
446	/// Run the full pipeline and send exactly one final `Done` on `tx` (the
447	/// caller's channel then closes naturally when this function returns and
448	/// `tx` is dropped).
449	pub(crate) async fn run_research(
450	    provider: OpenRouter,
451	    research_model: String,
452	    escalation_model: String,
453	    embedding_model: String,
454	    db_path: std::path::PathBuf,
455	    topic: String,
456	    gate_rx: Option<tokio::sync::oneshot::Receiver<Vec<String>>>,
457	    steer_rx: mpsc::UnboundedReceiver<String>,
458	    toolbox: Arc<ToolBox>,
459	    tx: mpsc::UnboundedSender<ResearchMsg>,
460	    session_id: String,
461	    space_id: String,
462	    space_name: String,
463	) {
464	    let known = local_known_chunks(&provider, &embedding_model, &db_path, &space_id, &topic).await;
465	    let ids = (session_id, space_id, space_name);
466	    let result = run_research_inner(
467	        &provider,
468	        &research_model,
469	        &escalation_model,
470	        &topic,
471	        &known,
472	        gate_rx,
473	        steer_rx,
474	        &db_path,
475	        &toolbox,
476	        &tx,
477	        &ids,
478	    )
479	    .await;
480	    let _ = tx.send((ids.0, ids.1, ids.2, ResearchUpdate::Done(result)));
481	}
482	
483	/// Top-k chunks from the space's files already relevant to `topic`, for the
484	/// Planner's "already known" context — silently empty when embeddings are
485	/// unconfigured, embedding fails, or the space has no files (never blocks
486	/// `/research` on any of those).
487	async fn local_known_chunks(
488	    provider: &OpenRouter,
489	    embedding_model: &str,
490	    db_path: &std::path::Path,
491	    space_id: &str,
492	    topic: &str,
493	) -> Vec<String> {
494	    if embedding_model.trim().is_empty() {
495	        return Vec::new();
496	    }
497	    let Ok(mut vecs) = provider
498	        .embed(embedding_model, vec![topic.to_string()])
499	        .await
500	    else {
501	        return Vec::new();
502	    };
503	    if vecs.is_empty() {
504	        return Vec::new();
505	    }
506	    let query = vecs.remove(0);
507	    let Ok(conn) = rusqlite::Connection::open(db_path) else {
508	        return Vec::new();
509	    };
510	    crate::db::semantic_chunks(&conn, space_id, &query, 5)
511	        .map(|hits| {
512	            hits.into_iter()
513	                .map(|(name, loc, text, _)| format!("{name} ({loc}): {text}"))
514	                .collect()
515	        })
516	        .unwrap_or_default()
517	}
