519	#[allow(clippy::too_many_arguments)]
520	async fn run_research_inner(
521	    provider: &OpenRouter,
522	    research_model: &str,
523	    escalation_model: &str,
524	    topic: &str,
525	    known: &[String],
526	    gate_rx: Option<tokio::sync::oneshot::Receiver<Vec<String>>>,
527	    mut steer_rx: mpsc::UnboundedReceiver<String>,
528	    db_path: &std::path::Path,
529	    toolbox: &Arc<ToolBox>,
530	    tx: &mpsc::UnboundedSender<ResearchMsg>,
531	    ids: &(String, String, String),
532	) -> Result<String, String> {
533	    send_stage(tx, ids, "planning", "");
534	    let mut questions = plan(provider, research_model, topic, known).await?;
535	
536	    // Plan-approval gate: show the sub-questions and wait for approve/edit,
537	    // auto-continuing after 60s so a backgrounded session never hangs.
538	    if let Some(gate_rx) = gate_rx {
539	        let _ = tx.send((
540	            ids.0.clone(),
541	            ids.1.clone(),
542	            ids.2.clone(),
543	            ResearchUpdate::PlanReady {
544	                questions: questions.clone(),
545	            },
546	        ));
547	        questions = match tokio::time::timeout(std::time::Duration::from_secs(60), gate_rx).await {
548	            Ok(Ok(edited)) if !edited.is_empty() => edited,
549	            // Timeout, dropped sender, or an empty edit — continue as planned.
550	            _ => questions,
551	        };
552	    }
553	
554	    let pinned = rusqlite::Connection::open(db_path)
555	        .ok()
556	        .and_then(|conn| crate::db::pinned_urls(&conn, &ids.0).ok())
557	        .unwrap_or_default();
558	
559	    let mut findings =
560	        run_searchers(provider, research_model, toolbox, &questions, tx, ids, 1).await;
561	    persist_session_sources(db_path, &ids.0, &findings);
562	
563	    let steers = drain_steers(&mut steer_rx).await;
564	    if !steers.is_empty() {
565	        for s in &steers {
566	            send_stage(tx, ids, "steer", s.clone());
567	        }
568	        let steered = run_searchers(provider, research_model, toolbox, &steers, tx, ids, 1).await;
569	        persist_session_sources(db_path, &ids.0, &steered);
570	        findings.extend(steered);
571	    }
572	
573	    send_stage(tx, ids, "synthesizing", "");
574	    let mut draft = complete_text(
575	        provider,
576	        research_model,
577	        synthesizer_messages(topic, &crate::tools::dedup_source_lines(&findings), &pinned),
578	    )
579	    .await?;
580	
581	    send_stage(tx, ids, "critiquing", "");
582	    let mut critique = parse_critique(
583	        &complete_text(provider, research_model, critic_messages(topic, &draft)).await?,
584	    );
585	
586	    if let Critique::Gaps(gaps) = &critique {
587	        let more = run_searchers(provider, research_model, toolbox, gaps, tx, ids, 2).await;
588	        persist_session_sources(db_path, &ids.0, &more);
589	        findings.extend(more);
590	
591	        let steers = drain_steers(&mut steer_rx).await;
592	        if !steers.is_empty() {
593	            for s in &steers {
594	                send_stage(tx, ids, "steer", s.clone());
595	            }
596	            let steered =
597	                run_searchers(provider, research_model, toolbox, &steers, tx, ids, 2).await;
598	            persist_session_sources(db_path, &ids.0, &steered);
599	            findings.extend(steered);
600	        }
601	
602	        send_stage(tx, ids, "re-synthesizing", "");
603	        draft = complete_text(
604	            provider,
605	            research_model,
606	            synthesizer_messages(topic, &crate::tools::dedup_source_lines(&findings), &pinned),
607	        )
608	        .await?;
609	        send_stage(tx, ids, "critiquing", "round 2");
610	        critique = parse_critique(
611	            &complete_text(provider, research_model, critic_messages(topic, &draft)).await?,
612	        );
613	    }
614	
615	    if let Critique::Contradiction(desc) = &critique {
616	        send_stage(tx, ids, "resolving a contradiction", "");
617	        let resolution = complete_text(
618	            provider,
619	            escalation_model,
620	            escalation_messages(topic, &draft, &findings, desc),
621	        )
622	        .await?;
623	        draft.push_str("\n\n");
624	        draft.push_str(&resolution);
625	    }
626	
627	    send_stage(tx, ids, "verifying", "");
628	    let verify_toolbox = Arc::new(
629	        ToolBox::research(
630	            None,
631	            None,
632	            "auto".to_string(),
633	            Vec::new(),
634	            Some(db_path.to_path_buf()),
635	        )
636	        .cache_only(),
637	    );
638	    let verified_raw = verify_with_quote_check(
639	        provider,
640	        research_model,
641	        verifier_messages(topic, &draft, &findings),
642	        verify_toolbox,
643	    )
644	    .await;
645	    let verified = if verified_raw.trim().is_empty() {
646	        draft.clone()
647	    } else {
648	        verified_raw
649	    };
650	
651	    send_stage(tx, ids, "writing final report", "");
652	    complete_text(
653	        provider,
654	        research_model,
655	        writer_messages(topic, &verified, &pinned),
656	    )
657	    .await
658	}
659	
660	/// Link every URL cited in `findings` into the session's source bundle
661	/// (they're already in `web_cache` from `fetch_url`'s write-through). Best
662	/// effort — a failed write never disturbs the pipeline.
663	fn persist_session_sources(db_path: &std::path::Path, session_id: &str, findings: &[String]) {
664	    let url_norms = crate::tools::cited_url_norms(findings);
665	    if url_norms.is_empty() {
666	        return;
667	    }
668	    if let Ok(conn) = rusqlite::Connection::open(db_path) {
669	        let _ = crate::db::add_session_sources(&conn, session_id, &url_norms);
670	    }
671	}
