673	impl super::App {
674	    /// `/research <topic>`: run the multi-agent research pipeline in a new
675	    /// background session. One job at a time. `/research! <topic>` skips the
676	    /// plan-approval gate.
677	    pub(crate) fn start_research(&mut self, topic: &str) {
678	        self.start_research_with_gate(topic, true)
679	    }
680	
681	    /// `/steer <text>`: queue an extra instruction for the running research
682	    /// job, picked up at the next round boundary. No-op with a status message
683	    /// if no research job is running.
684	    pub(crate) fn steer_research(&mut self, text: &str) {
685	        if text.is_empty() {
686	            self.status = "usage: /steer <what to also look into>".to_string();
687	            return;
688	        }
689	        match &self.research_steer_tx {
690	            Some(tx) if tx.send(text.to_string()).is_ok() => {
691	                self.status = format!("queued steer: {text}");
692	            }
693	            _ => self.status = "no research job is running".to_string(),
694	        }
695	    }
696	
697	    /// `/research` with no topic: distill one from the last ~20 chat turns
698	    /// (one cheap completion, same background-channel shape as
699	    /// `maybe_generate_title`) then hand it to `start_research_with_gate`
700	    /// exactly as if it had been typed — the existing plan-approval gate
701	    /// still lets you bail or edit before searchers run.
702	    pub(crate) fn start_research_from_chat(&mut self) {
703	        if self.research_topic_rx.is_some() {
704	            self.status = "already scoping a topic from this chat…".to_string();
705	            return;
706	        }
707	        if self.research_rx.is_some() {
708	            self.status = "a research job is already running".to_string();
709	            return;
710	        }
711	        let (Some(provider), Some(model)) = (self.provider.clone(), self.current_model.clone())
712	        else {
713	            self.status = "no model configured — set one in /key or /model".to_string();
714	            return;
715	        };
716	        let convo: String = self
717	            .messages
718	            .iter()
719	            .filter(|m| m.role == "user" || m.role == "assistant")
720	            .rev()
721	            .take(20)
722	            .collect::<Vec<_>>()
723	            .into_iter()
724	            .rev()
725	            .map(|m| {
726	                format!(
727	                    "{}: {}",
728	                    m.role,
729	                    m.content.chars().take(500).collect::<String>()
730	                )
731	            })
732	            .collect::<Vec<_>>()
733	            .join("\n");
734	        if convo.trim().is_empty() {
735	            self.status = "nothing to scope yet — chat first, or use /research <topic>".to_string();
736	            return;
737	        }
738	        let (tx, rx) = mpsc::unbounded_channel();
739	        self.research_topic_rx = Some(rx);
740	        self.status = "scoping a research topic from this chat…".to_string();
741	        tokio::spawn(async move {
742	            let prompt = format!(
743	                "Based on this conversation, reply with ONLY a single-line research topic \
744	                 or question suitable for a multi-source research task. No preamble, no \
745	                 quotes, no markdown.\n\n{convo}"
746	            );
747	            let msgs = vec![ChatMessage::text("user", prompt)];
748	            let result = provider
749	                .complete(&model, msgs)
750	                .await
751	                .map(|s| s.trim().to_string())
752	                .map_err(|e| e.to_string());
753	            let _ = tx.send(result);
754	        });
755	    }
