 12	/// Live per-searcher activity: the same `research_stage` rows shown inline in
 13	/// the transcript (one per searcher label, updated in place as
 14	/// Status/ToolCall events arrive — see `run_searcher` in `app/research.rs`),
 15	/// isolated into their own view plus a steer input line.
 16	pub(crate) fn render(f: &mut Frame, app: &App) {
 17	    let area = crate::ui::centered(f.area(), 76, 70);
 18	    f.render_widget(Clear, area);
 19	
 20	    let dim = Style::default().fg(app.theme.fg_dim);
 21	    let rows: Vec<&crate::db::Message> = app
 22	        .messages
 23	        .iter()
 24	        .filter(|m| m.role == "research_stage")
 25	        .collect();
 26	    let items: Vec<ListItem> = if rows.is_empty() {
 27	        vec![ListItem::new(Line::from(Span::styled(
 28	            "waiting for the first update…",
 29	            dim,
 30	        )))]
 31	    } else {
 32	        rows.iter()
 33	            .map(|m| {
 34	                ListItem::new(Line::from(Span::styled(
 35	                    m.content.clone(),
 36	                    Style::default().fg(app.theme.fg),
 37	                )))
 38	            })
 39	            .collect()
 40	    };
 41	
 42	    let title = format!(
 43	        " research — steer: {}▏  (Enter send · Esc close) ",
 44	        app.research_live_input
 45	    );
 46	    let list = List::new(items).block(chrome::popup_block(
 47	        Line::from(Span::styled(
 48	            title,
 49	            Style::default().add_modifier(Modifier::BOLD),
 50	        )),
 51	        &app.theme,
 52	    ));
 53	    f.render_widget(list, area);
 54	}
