 56	pub(crate) fn handle_key(app: &mut App, key: KeyEvent) -> Result<()> {
 57	    match key.code {
 58	        KeyCode::Esc => app.popup = crate::app::Popup::None,
 59	        KeyCode::Enter => {
 60	            let text = app.research_live_input.trim().to_string();
 61	            app.research_live_input.clear();
 62	            app.steer_research(&text);
 63	        }
 64	        KeyCode::Backspace => {
 65	            app.research_live_input.pop();
 66	        }
 67	        KeyCode::Char(c) => app.research_live_input.push(c),
 68	        _ => {}
 69	    }
 70	    Ok(())
