117	/// Split a popup's inner area into (list area, detail-strip area). The strip
118	/// is sized to `desc`'s wrapped height (0 when `desc` is empty, so an
119	/// item with no description doesn't waste a row).
120	pub(crate) fn split_with_detail(area: Rect, desc: &str) -> (Rect, Rect) {
121	    if desc.trim().is_empty() {
122	        return (area, Rect { height: 0, ..area });
123	    }
124	    let inner_w = area.width.max(1) as usize;
125	    let wrapped = textwrap::wrap(desc, inner_w).len().max(1) as u16;
126	    let desc_h = wrapped.min(MAX_DETAIL_ROWS) + 1; // +1 for the divider
127	    let chunks = Layout::vertical([Constraint::Min(1), Constraint::Length(desc_h)]).split(area);
128	    (chunks[0], chunks[1])
129	}
