131	/// Render the wrapped description strip: a dim divider rule, then plain
132	/// wrapped text — no markdown, no per-word styling.
133	pub(crate) fn render_detail(f: &mut Frame, area: Rect, desc: &str, theme: &Theme) {
134	    if area.height == 0 || desc.trim().is_empty() {
135	        return;
136	    }
137	    let block = Block::default()
138	        .borders(Borders::TOP)
139	        .border_style(Style::default().fg(theme.border_dim));
140	    let inner = block.inner(area);
141	    f.render_widget(block, area);
142	    let p = Paragraph::new(desc.to_string())
143	        .style(Style::default().fg(theme.fg_dim))
144	        .wrap(Wrap { trim: true });
145	    f.render_widget(p, inner);
146	}
