 20	use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
 21	
 22	// Shared state-machine helpers for the session/space/skills popups, which all
 23	// hand-roll the same "Browse list (filter as you type) / Edit text field /
 24	// confirm-delete" shape. Each popup's own `handle_key` still owns *what*
 25	// happens for a given action (e.g. what "Close" clears) — these helpers only
 26	// centralize *which* keys map to which action, since that mapping is
 27	// identical across the 3 (module-doc'd divergences: skills has no rename and
 28	// no Browse-mode text filter; space gates its delete-confirm key on the
 29	// selected space not being the default one — that guard stays in space.rs).
 30	
 31	/// Actions available while browsing a popup's list (the default mode).
 32	///
 33	/// `Close`/`MoveUp`/`MoveDown`/`Backspace`/`Filter` are common to all 3
 34	/// popups' Browse mode. `Create` and `Rename` are gated by
 35	/// `classify_browse_key`'s `supports_create`/`supports_rename` flags so a
 36	/// popup that doesn't support one simply never receives it (matching the
 37	/// current behavior where, e.g., skills' Browse arm has no Ctrl+R case at
 38	/// all and falls through to its `_ => {}`).
 39	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 40	pub(super) enum BrowseAction {
 41	    Close,
 42	    Filter(char),
 43	    Backspace,
 44	    MoveUp,
 45	    MoveDown,
 46	    Create,
 47	    Rename,
 48	    ConfirmDelete,
 49	}
 50	
 51	/// Maps a keypress to a `BrowseAction` for a popup's Browse mode.
 52	///
 53	/// This does NOT handle Enter — session and space each treat Enter as
 54	/// "open/select the highlighted item", which is entirely popup-specific
 55	/// (`confirm_session`/`confirm_space`) and has no skills equivalent, so each
 56	/// `handle_key` still matches `KeyCode::Enter` itself before falling back to
 57	/// this classifier.
 58	pub(super) fn classify_browse_key(
 59	    key: KeyEvent,
 60	    supports_create: bool,
 61	    supports_rename: bool,
 62	) -> Option<BrowseAction> {
 63	    let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
 64	    match key.code {
 65	        KeyCode::Esc => Some(BrowseAction::Close),
 66	        KeyCode::Up => Some(BrowseAction::MoveUp),
 67	        KeyCode::Down => Some(BrowseAction::MoveDown),
 68	        KeyCode::Char('n') if ctrl && supports_create => Some(BrowseAction::Create),
 69	        KeyCode::Char('r') if ctrl && supports_rename => Some(BrowseAction::Rename),
 70	        KeyCode::Char('d') if ctrl => Some(BrowseAction::ConfirmDelete),
 71	        KeyCode::Backspace => Some(BrowseAction::Backspace),
 72	        KeyCode::Char(c) if !ctrl => Some(BrowseAction::Filter(c)),
 73	        _ => None,
 74	    }
 75	}
 76	
 77	/// Actions available while editing a text field (rename / create / install
 78	/// prompt). Identical across all 3 popups.
 79	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 80	pub(super) enum EditAction {
 81	    Cancel,
 82	    Save,
 83	    Backspace,
 84	    Push(char),
 85	}
 86	
 87	pub(super) fn classify_edit_key(key: KeyEvent) -> Option<EditAction> {
 88	    match key.code {
 89	        KeyCode::Esc => Some(EditAction::Cancel),
 90	        KeyCode::Enter => Some(EditAction::Save),
 91	        KeyCode::Backspace => Some(EditAction::Backspace),
 92	        KeyCode::Char(c) => Some(EditAction::Push(c)),
 93	        _ => None,
 94	    }
 95	}
 96	
 97	/// Actions available while a delete confirmation is showing. Identical
 98	/// across all 3 popups: Ctrl+D confirms, Esc cancels, everything else is a
 99	/// no-op.
100	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
101	pub(super) enum ConfirmDeleteAction {
102	    Yes,
103	    No,
104	}
105	
106	pub(super) fn classify_confirm_delete_key(key: KeyEvent) -> Option<ConfirmDeleteAction> {
107	    let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
108	    match key.code {
109	        KeyCode::Char('d') if ctrl => Some(ConfirmDeleteAction::Yes),
110	        KeyCode::Esc => Some(ConfirmDeleteAction::No),
111	        _ => None,
112	    }
113	}

