  1225	    /// Save the finished report into the job's own space (not necessarily
  1226	    /// the currently active one — the user may have switched spaces while
  1227	    /// the job ran), named `research-<slug>-<timestamp>.md`. Only refreshes
  1228	    /// the files cache / triggers a rescan if that space is still active;
  1229	    /// otherwise the file sits on disk and gets picked up next time that
  1230	    /// space's /files is opened, same as any externally-dropped file.
  1231	    fn save_research_report(
  1232	        &mut self,
  1233	        space_id: &str,
  1234	        space_name: &str,
  1235	        topic: &str,
  1236	        report: &str,
  1237	    ) {
  1238	        let dir = self.space.files_dir(space_name);
  1239	        if std::fs::create_dir_all(&dir).is_err() {
  1240	            return;
  1241	        }
  1242	        let slug = super::sessions::slugify(topic);
  1243	        let stamp = chrono::Local::now().format("%Y%m%d-%H%M%S");
  1244	        let name = format!("research-{slug}-{stamp}.md");
  1245	        if std::fs::write(dir.join(&name), report).is_err() {
  1246	            return;
  1247	        }
  1248	        // Index the report's cited sources for list_citations.
  1249	        let citations = crate::citations::parse_citations(report);
  1250	        if !citations.is_empty() {
  1251	            // Titles aren't in the Sources-list format; index url only.
  1252	            let rows: Vec<(String, Option<String>)> =
  1253	                citations.into_iter().map(|(_, url)| (url, None)).collect();
  1254	            let _ = self.db.add_citations(space_id, &name, &rows);
  1255	        }
  1256	        if space_id == self.active_space.id {
  1257	            self.rescan_files();
  1258	        }
  1259	    }
  1260	}
