 47	    pub(crate) fn resolve_feature_model_backend(
 48	        &self,
 49	        configured_id: &str,
 50	        default: fn(&OpenRouter) -> &'static str,
 51	    ) -> Option<(OpenRouter, String)> {
 52	        let configured_id = configured_id.trim();
 53	        if !configured_id.is_empty()
 54	            && let Some((provider, raw)) = self.resolve_model_backend(configured_id)
 55	            && self.resolved_model_looks_valid(configured_id, provider.backend_tag(), &raw)
 56	        {
 57	            return Some((provider, raw));
 58	        }
 59	
 60	        let provider = self
 61	            .current_model
 62	            .as_deref()
 63	            .and_then(|id| self.resolve_model_backend(id).map(|(provider, _)| provider))
 64	            .or_else(|| {
 65	                self.backends
 66	                    .configured_tags()
 67	                    .first()
 68	                    .and_then(|tag| self.backends.get(*tag).cloned())
 69	            })?;
 70	        Some((provider.clone(), default(&provider).to_string()))
 71	    }
