 73	    fn resolved_model_looks_valid(&self, original_id: &str, backend: BackendTag, raw: &str) -> bool {
 74	        if self.models.is_empty() {
 75	            // The classic bad state is a legacy OpenRouter id like
 76	            // `google/gemini-*` being resolved against OpenAI/Codex/Go because
 77	            // OpenRouter is not configured. Those backends' built-in defaults
 78	            // do not contain `/`, so treat slashy bare ids as OpenRouter-only.
 79	            return backend == BackendTag::OpenRouter || !original_id.contains('/');
 80	        }
 81	        self.models
 82	            .iter()
 83	            .any(|m| m.backend == backend && m.id == raw)
 84	    }
