 14	const OPENAI_BASE: &str = "https://api.openai.com/v1";
 15	const CODEX_BASE: &str = "https://chatgpt.com/backend-api";
 16	/// The general Zen catalog: free-tier and pay-per-token models, plus
 17	/// whatever a Go subscription adds. This is the default/fallback base.
 18	const OPENCODE_ZEN_BASE: &str = "https://opencode.ai/zen/v1";
 19	/// The flat-fee Go-subscription bundle — a *different* endpoint from Zen's
 20	/// general catalog, even though it's the same account key. Requests for a
 21	/// Go-bundled model must go here, not to Zen general, or they'd be billed
 22	/// per-token instead of covered by the flat $10/mo.
 23	const OPENCODE_GO_BASE: &str = "https://opencode.ai/zen/go/v1";
 24	/// Prefix on a Model id (from `list_models`) marking it as a flat-fee Go
 25	/// model rather than a general Zen one — stripped before it's ever sent to
 26	/// the API; only used to pick which of the two bases above to hit.
 27	const OPENCODE_GO_PREFIX: &str = "go:";
 28	/// Hard cap on tool round-trips per response, so a model that keeps calling
 29	/// tools can't loop forever. The default for interactive chat; background
 30	/// jobs (e.g. deep-research searcher agents) pass their own smaller budget.
 31	pub(crate) const MAX_TOOL_ITERS: usize = 25;
