 33	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
 34	enum ProviderFlavor {
 35	    OpenRouter,
 36	    OpenAi,
 37	    OpenAiCodex,
 38	    /// OpenCode Go: a low-cost subscription bundling several open coding
 39	    /// models behind a fully OpenAI-compatible endpoint — no special
 40	    /// request/response handling needed, unlike Codex.
 41	    OpencodeGo,
 42	}
