 44	#[derive(Clone)]
 45	pub struct OpenRouter {
 46	    client: reqwest::Client,
 47	    key: String,
 48	    flavor: ProviderFlavor,
 49	}
 50	
 51	impl ProviderFlavor {
 52	    fn base(self) -> &'static str {
 53	        match self {
 54	            ProviderFlavor::OpenRouter => OPENROUTER_BASE,
 55	            ProviderFlavor::OpenAi => OPENAI_BASE,
 56	            ProviderFlavor::OpenAiCodex => CODEX_BASE,
 57	            ProviderFlavor::OpencodeGo => OPENCODE_ZEN_BASE,
 58	        }
 59	    }
 60	
 61	    fn supports_reasoning(self, m: &ModelEntry) -> bool {
 62	        match self {
 63	            ProviderFlavor::OpenRouter => m.supported_parameters.iter().any(|p| p == "reasoning"),
 64	            ProviderFlavor::OpenAi => {
 65	                let id = m.id.as_str();
 66	                id.starts_with("o") || id.starts_with("gpt-5")
 67	            }
 68	            ProviderFlavor::OpenAiCodex => true,
 69	            // Several Go models (DeepSeek, Qwen, GLM) support a thinking
 70	            // mode; no catalog metadata to check, so offer the toggle on
 71	            // all of them rather than silently hiding it on ones that do.
 72	            ProviderFlavor::OpencodeGo => true,
 73	        }
 74	    }
 75	
 76	    fn supports_images(self, m: &ModelEntry) -> Option<bool> {
 77	        match self {
 78	            ProviderFlavor::OpenRouter => None,
 79	            ProviderFlavor::OpenAi => {
 80	                let id = m.id.as_str();
 81	                Some(
 82	                    id.contains("gpt-4o")
 83	                        || id.contains("gpt-4.1")
 84	                        || id.starts_with("gpt-5")
 85	                        || id.starts_with("o3")
 86	                        || id.starts_with("o4"),
 87	                )
 88	            }
 89	            ProviderFlavor::OpenAiCodex => Some(true),
 90	            ProviderFlavor::OpencodeGo => Some(false),
 91	        }
 92	    }
 93	
 94	    fn add_stream_usage(self, obj: &mut serde_json::Map<String, serde_json::Value>) {
 95	        match self {
 96	            // Ask OpenRouter for exact token accounting in the final chunk.
 97	            ProviderFlavor::OpenRouter => {
 98	                obj.insert("usage".into(), serde_json::json!({ "include": true }));
 99	            }
100	            // OpenAI (and OpenCode Go, which mirrors OpenAI's API shape)
101	            // put the equivalent switch under stream_options.
102	            ProviderFlavor::OpenAi | ProviderFlavor::OpencodeGo => {
103	                obj.insert(
104	                    "stream_options".into(),
105	                    serde_json::json!({ "include_usage": true }),
106	                );
107	            }
108	            ProviderFlavor::OpenAiCodex => {}
109	        }
110	    }
111	
112	    fn add_reasoning_effort(
113	        self,
114	        obj: &mut serde_json::Map<String, serde_json::Value>,
115	        effort: &str,
116	    ) {
117	        match self {
118	            ProviderFlavor::OpenRouter => {
119	                obj.insert("reasoning".into(), serde_json::json!({ "effort": effort }));
120	            }
121	            ProviderFlavor::OpenAi | ProviderFlavor::OpencodeGo => {
122	                obj.insert("reasoning_effort".into(), serde_json::json!(effort));
123	            }
