 58	    /// Split a composite model id (see `composite_id`) into the backend
 59	    /// that owns it and the raw id to actually send in a request, and
 60	    /// clone out that backend's provider. `None` if the composite id's
 61	    /// backend isn't configured (e.g. its login was removed).
 62	    pub fn resolve(&self, composite_id: &str) -> Option<(OpenRouter, String)> {
 63	        for tag in [
 64	            BackendTag::OpenAi,
 65	            BackendTag::OpencodeGo,
 66	            BackendTag::Codex,
 67	        ] {
 68	            if let Some(raw) = composite_id.strip_prefix(tag.key_prefix()) {
 69	                return self.get(tag).cloned().map(|p| (p, raw.to_string()));
 70	            }
 71	        }
 72	        // No known prefix matched => a bare id. Prefer OpenRouter for
 73	        // backwards compatibility with existing stored model choices; if it
 74	        // isn't configured (tests/single-backend setups), use the first
 75	        // configured backend so unprefixed defaults still work.
 76	        self.get(BackendTag::OpenRouter)
 77	            .or_else(|| self.configured_tags().first().and_then(|t| self.get(*t)))
 78	            .cloned()
 79	            .map(|p| (p, composite_id.to_string()))
 80	    }
 81	}
